function forgivingLookup(words: string[], queries: string[]): string[] {
  const mask = (s: string) => s.toLowerCase().replace(/[aeiou]/g, "*");
  return queries.map(q => {
    if (words.includes(q)) return q;
    const lq = q.toLowerCase();
    const a = words.find(w => w.toLowerCase() === lq);
    if (a !== undefined) return a;
    const mq = mask(q);
    const b = words.find(w => mask(w) === mq);
    return b === undefined ? "" : b;
  });
}

