function forgivingLookup(words: string[], queries: string[]): string[] {
  const mask = (s: string) => s.toLowerCase().replace(/[aeiou]/g, "*");
  const exact = new Set(words);
  const lower = new Map<string, string>(), vow = new Map<string, string>();
  for (const w of words) {
    const l = w.toLowerCase(), m = mask(w);
    if (!lower.has(l)) lower.set(l, w); // keep the first word only
    if (!vow.has(m)) vow.set(m, w);
  }
  return queries.map(q => {
    if (exact.has(q)) return q;
    return lower.get(q.toLowerCase()) ?? vow.get(mask(q)) ?? "";
  });
}

